/// Standalone LAN client. Names are rendered only through textContent.
enum WifiPage {
  static let html = #"""
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>nanoPlayer · Wi-Fi 传输</title>
<style>
:root{color-scheme:light dark;--bg:light-dark(#f5f6fa,#17191f);--panel:light-dark(#fff,#252932);--text:light-dark(#222734,#f1f3f7);--muted:light-dark(#626d7e,#b0bacb);--line:light-dark(#e1e5ec,#3e4551);--accent:light-dark(#345fda,#a9bfff);--active:light-dark(#fff,#13224c);--danger:light-dark(#b72c42,#ffa1b0)}
*{box-sizing:border-box}body{font:16px/1.5 system-ui;margin:0;background:var(--bg);color:var(--text);padding:24px;max-width:1060px;margin-inline:auto}h1{font-size:26px;font-weight:600}h2{font-size:20px}small,p{color:var(--muted)}button,input{font:inherit;border:1px solid var(--line);border-radius:10px;padding:10px 14px;background:var(--panel);color:var(--text);min-height:44px;max-width:100%}button{cursor:pointer}button:disabled{opacity:.5;cursor:wait}.primary{background:var(--accent);color:var(--active);border-color:transparent}.danger{color:var(--danger)}header,.toolbar,.entry,.buttons{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.toolbar{margin:20px 0}header h1{flex:1}.panel{background:var(--panel);padding:20px;border:1px solid var(--line);border-radius:16px}.entry{border-bottom:1px solid var(--line);padding:12px 0;flex-wrap:nowrap}.entry:last-child{border:0}.entry .open{flex:1;text-align:left;border:0;background:none;overflow-wrap:anywhere;min-width:0}.entry small{display:block}.upload{margin-top:20px;border:1px dashed var(--line);border-radius:14px;padding:20px}.entry details{position:relative}.entry summary{padding:10px;cursor:pointer;list-style:none}.entry details .buttons{position:absolute;right:0;top:44px;min-width:140px;background:var(--panel);padding:10px;border:1px solid var(--line);border-radius:12px;z-index:2;display:grid}.path{overflow-wrap:anywhere;color:var(--muted)}#status{white-space:pre-wrap;overflow-wrap:anywhere;padding-block:12px}dialog{background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:16px;width:min(92%,480px);max-height:85vh;overflow:auto}dialog::backdrop{background:#0007}dialog label{display:grid;gap:8px;margin-bottom:16px}#login{max-width:420px;margin:50px auto}#login input{width:100%;margin-block:12px}#target-list{display:grid;gap:8px;margin:16px 0}[hidden]{display:none!important}.progress{margin-block:10px}.progress progress{width:100%}@media(max-width:520px){body{padding:14px}.panel{padding:12px}h1{font-size:22px}.entry{gap:4px}}
</style>
<header><h1>nanoPlayer <small>Wi-Fi 传输</small></h1><button id="logout" hidden>断开连接</button></header>
<p>仅管理 nanoPlayer 自有资源库。保持手机前台，局域网 HTTP 传输不加密。</p>
<form id="login" class="panel"><h2>连接资源库</h2><label for="code">手机上显示的八位配对码</label><input id="code" inputmode="numeric" pattern="[0-9]{8}" maxlength="8" required autocomplete="off"><button class="primary">配对并打开</button></form>
<div id="workspace" hidden><div class="toolbar"><button id="root">根目录</button><button id="up">上一级</button><button id="refresh">刷新</button><button id="create">新建文件夹</button><button id="trash">回收站</button></div><p id="path" class="path"></p><section id="entries" class="panel" aria-label="目录内容"></section><section id="upload" class="upload"><h2>上传到当前目录</h2><p id="destination"></p><input id="files" type="file" multiple accept=".mp3,.m4a,.aac,.flac,.wav,.aiff,.aif,.alac,.ogg,.opus"><div class="toolbar"><button id="send" class="primary">开始上传</button><button id="retry">重试失败项</button></div><small>单个文件最大 512MB，同名保留两份。上传前请确认当前位置。</small><div id="progress" aria-live="polite"></div></section></div>
<div id="status" role="status" aria-live="polite"></div>
<dialog id="editor"><form method="dialog"><h2 id="edit-title"></h2><label>名称<input id="name" required></label><div class="buttons"><button value="cancel" formnovalidate>取消</button><button id="save" value="save" class="primary">保存</button></div></form></dialog>
<dialog id="confirm"><h2 id="confirm-title"></h2><p id="confirm-text"></p><div class="buttons"><button id="cancel-confirm">取消</button><button id="accept-confirm" class="danger">确认</button></div></dialog>
<dialog id="target"><h2>移动到文件夹</h2><p id="target-path" class="path"></p><button id="target-up">上一级</button><div id="target-list"></div><div class="buttons"><button id="target-cancel">取消</button><button id="target-choose" class="primary">移动到此文件夹</button></div></dialog>
<script>
const $=id=>document.getElementById(id);let token='',current='',rootId='',listing=null,trashMode=false,busy=false,failed=[],editing=null,moving=null,targetId='',targetListing=null;
function text(id,value){$(id).textContent=value}function status(v){text('status',v)}
function button(label,fn,cls=''){const b=document.createElement('button');b.type='button';b.textContent=label;b.className=cls;b.onclick=()=>safe(fn);return b}
async function response(r){const value=await r.text();if(!r.ok){if(r.status===401){token='';$('workspace').hidden=true;$('login').hidden=false;$('logout').hidden=true}throw new Error(value)}return value?JSON.parse(value):{}}
async function api(action,args={}){return response(await fetch('/api',{method:'POST',headers:{'X-Session-Token':token,'Content-Type':'application/json'},body:JSON.stringify({action,...(current?{id:current}:{}),revision:listing?.revision,...args})}))}
async function safe(fn){try{await fn()}catch(e){status(e.message||String(e))}}
async function load(id=current){listing=await api('list',id?{id}:{});current=listing.currentId;rootId=listing.rootId;render()}
function render(){text('path',trashMode?'nanoPlayer / 回收站':listing.path);text('destination',listing.path);$('upload').hidden=trashMode;$('entries').replaceChildren();const entries=trashMode?listing.trash:listing.entries;if(!entries.length){text('entries',trashMode?'回收站为空':'此文件夹为空');return}for(const n of entries){const row=document.createElement('div');row.className='entry';const open=button((trashMode?'♲ ':n.directory?'▱ ':'♫ ')+n.name,async()=>{if(n.directory&&!trashMode){trashMode=false;await load(n.id)}} ,'open');if(!n.directory&&!trashMode)open.disabled=true;row.append(open);if(trashMode){row.append(button('恢复',async()=>{await api('restore',{trashId:n.id});await afterWrite('已恢复；保留原歌曲记录，同名保留两份。')}));row.append(button('恢复到…',()=>chooseTarget({trashId:n.id,name:n.name})));row.append(button('彻底删除',()=>ask('彻底删除？','删除后无法恢复“'+n.name+'”。',async()=>{await api('purge',{trashId:n.id});await afterWrite('已彻底删除。')}),'danger'))}else if(n.directory){const details=document.createElement('details'),summary=document.createElement('summary'),actions=document.createElement('div');summary.textContent='•••';summary.setAttribute('aria-label','更多操作 '+n.name);actions.className='buttons';actions.append(button('重命名',()=>edit('rename',n)),button('移动到…',()=>chooseTarget(n)),button('删除目录',()=>ask('移入回收站？','“'+n.name+'”含 '+(n.directoryCount||0)+' 个子目录、'+(n.audioCount||0)+' 首音乐，将从音乐库及队列移除，可恢复。',async()=>{await api('trash',{id:n.id});await afterWrite('已移入回收站。')}),'danger'));details.append(summary,actions);row.append(details)}$('entries').append(row)}}
async function afterWrite(message){status(message+' 正在同步手机索引…');await new Promise(r=>setTimeout(r,1400));await load()}
function edit(action,item){editing={action,item};text('edit-title',action==='create'?'新建文件夹':'重命名');$('name').value=item?.name||'';$('editor').showModal();$('name').focus()}
$('editor').addEventListener('close',()=>{if($('editor').returnValue!=='save')return;safe(async()=>{const name=$('name').value.trim();if(!name)throw Error('名称不能为空');await api(editing.action,{id:editing.item?.id||current,name});await afterWrite('目录已保存。')})});
let accept=null;function ask(title,message,fn){text('confirm-title',title);text('confirm-text',message);accept=fn;$('confirm').showModal()}
$('cancel-confirm').onclick=()=>$('confirm').close();$('accept-confirm').onclick=()=>{$('confirm').close();safe(accept)};
async function chooseTarget(item){moving=item;text('target-choose',item.trashId?'恢复到此文件夹':'移动到此文件夹');targetId=rootId;await loadTargets();$('target').showModal()}
async function loadTargets(){targetListing=await api('list',{id:targetId});text('target-path',targetListing.path);$('target-list').replaceChildren();for(const n of targetListing.entries.filter(n=>n.directory&&n.id!==moving.id))$('target-list').append(button(n.name,async()=>{targetId=n.id;await loadTargets()}))}
$('target-up').onclick=()=>safe(async()=>{targetId=targetListing.parentId;await loadTargets()});$('target-cancel').onclick=()=>$('target').close();$('target-choose').onclick=()=>safe(async()=>{await api(moving.trashId?'restore':'move',{id:moving.id||current,trashId:moving.trashId,targetId,revision:targetListing.revision});$('target').close();await afterWrite('已移动。')});
$('login').onsubmit=e=>{e.preventDefault();safe(async()=>{const data=await response(await fetch('/pair',{method:'POST',headers:{'X-Pairing-Code':$('code').value}}));token=data.token;$('code').value='';await load();$('login').hidden=true;$('workspace').hidden=false;$('logout').hidden=false;status('已连接。外部只读来源不会在浏览器中开放。')})};
$('logout').onclick=()=>safe(async()=>{await response(await fetch('/logout',{method:'POST',headers:{'X-Session-Token':token}}));token='';listing=null;current='';$('workspace').hidden=true;$('login').hidden=false;$('logout').hidden=true;status('已断开，本浏览器会话已失效。')});
$('root').onclick=()=>safe(async()=>{trashMode=false;await load(rootId)});$('up').onclick=()=>safe(async()=>{trashMode=false;await load(listing.parentId)});$('refresh').onclick=()=>safe(()=>load());$('create').onclick=()=>edit('create');$('trash').onclick=()=>safe(async()=>{trashMode=!trashMode;await load()});
function upload(file,target,progress){return new Promise((resolve,reject)=>{if(!file.size||file.size>512*1024*1024){reject(Error('单文件须大于 0 且不超过 512MB'));return}const x=new XMLHttpRequest();x.open('POST','/upload');x.setRequestHeader('X-Session-Token',token);x.setRequestHeader('X-Directory-Id',target);x.setRequestHeader('X-File-Name',encodeURIComponent(file.name));x.upload.onprogress=e=>{if(e.lengthComputable)progress.value=e.loaded/e.total};x.onload=()=>{x.status>=200&&x.status<300?resolve():reject(Error(x.responseText||'上传失败'))};x.onerror=()=>reject(Error('连接中断，请重试'));x.send(file)})}
async function send(retry){if(busy)return;const tasks=retry?failed:[...$('files').files].map(file=>({file,target:current}));failed=[];if(!tasks.length){status('请先选择文件');return}busy=true;['send','retry','create','root','up','trash'].forEach(id=>$(id).disabled=true);$('progress').replaceChildren();try{for(const task of tasks){const line=document.createElement('div'),label=document.createElement('span'),p=document.createElement('progress');line.className='progress';p.max=1;p.value=0;label.textContent=task.file.name+' · 上传中';line.append(label,p);$('progress').append(line);try{await upload(task.file,task.target,p);p.value=1;label.textContent=task.file.name+' · 完成'}catch(e){failed.push(task);label.textContent=task.file.name+' · '+e.message}}await load();status('上传完成。失败 '+failed.length+' 项；失败项保留原目标，可重试。')}finally{busy=false;['send','retry','create','root','up','trash'].forEach(id=>$(id).disabled=false)}}
$('send').onclick=()=>safe(()=>send(false));$('retry').onclick=()=>safe(()=>send(true));
</script></html>
"""#
}
